using PaymentAuthorization.Domain;
namespace PaymentAuthorization.Application;
/// <summary>Authorizes one payment and keeps a receipt of what the provider answered.</summary>
public sealed class AuthorizePayment(IPaymentGateway gateway, IReceiptStore receipts)
{
    public async Task<AuthorizationOutcome> HandleAsync(string reference, Money amount, CancellationToken cancellationToken = default)
    {
        var outcome = await gateway.AuthorizeAsync(reference, amount, cancellationToken);
        await receipts.SaveAsync(reference, $"{amount.Currency} {amount.Amount} -> {outcome}", cancellationToken);
        return outcome;
    }
}
using PaymentAuthorization.Domain;
namespace PaymentAuthorization.Application;
/// <summary>Outbound gateway to the payment provider.</summary>
public interface IPaymentGateway
{
    Task<AuthorizationOutcome> AuthorizeAsync(string reference, Money amount, CancellationToken cancellationToken);
}
namespace PaymentAuthorization.Application;
/// <summary>Outbound store keeping one receipt per authorization attempt.</summary>
public interface IReceiptStore
{
    Task SaveAsync(string reference, string body, CancellationToken cancellationToken);
}
namespace PaymentAuthorization.Domain;
/// <summary>What the payment provider decided about one authorization request.</summary>
public enum AuthorizationOutcome
{
    Declined = 0,
    Approved = 1,
}
namespace PaymentAuthorization.Domain;
/// <summary>An amount and the currency it is expressed in.</summary>
public readonly record struct Money
{
    public Money(decimal amount, string currency)
    {
        if (amount <= 0) throw new ArgumentOutOfRangeException(nameof(amount), "An amount must be positive.");
        if (string.IsNullOrWhiteSpace(currency)) throw new ArgumentException("A currency is required.", nameof(currency));
        Amount = amount;
        Currency = currency.ToUpperInvariant();
    }
    public decimal Amount { get; }
    public string Currency { get; }
}
using PaymentAuthorization.Application;
namespace PaymentAuthorization.Infrastructure;
/// <summary>Keeps one receipt file per reference under a root directory.</summary>
public sealed class FileSystemReceiptStore(string rootDirectory) : IReceiptStore
{
    public async Task SaveAsync(string reference, string body, CancellationToken cancellationToken)
    {
        Directory.CreateDirectory(rootDirectory);
        var path = Path.Combine(rootDirectory, $"{reference}.txt");
        await File.WriteAllTextAsync(path, body, cancellationToken);
    }
}
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
namespace PaymentAuthorization.Infrastructure;
/// <summary>
/// Talks to the provider's REST API: POST /v1/authorizations, and read back the decision.
/// The provider answers 200 with {"status":"approved"|"declined"} and 402 when it refuses
/// the request outright.
/// </summary>
public sealed class HttpPaymentGateway(HttpClient client) : IPaymentGateway
{
    public async Task<AuthorizationOutcome> AuthorizeAsync(string reference, Money amount, CancellationToken cancellationToken)
    {
        var request = new AuthorizationRequest(reference, amount.Amount, amount.Currency);
        using var response = await client.PostAsJsonAsync("/v1/authorizations", request, cancellationToken);
        if (response.StatusCode == System.Net.HttpStatusCode.PaymentRequired) return AuthorizationOutcome.Declined;
        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<AuthorizationResponse>(cancellationToken);
        return body?.Status == "approved" ? AuthorizationOutcome.Approved : AuthorizationOutcome.Declined;
    }
    private sealed record AuthorizationRequest(
        [property: JsonPropertyName("reference")] string Reference,
        [property: JsonPropertyName("amount")] decimal Amount,
        [property: JsonPropertyName("currency")] string Currency);
    private sealed record AuthorizationResponse(
        [property: JsonPropertyName("status")] string Status);
}
