using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

// Kept out of the UnitTest project on purpose so the fast per-save suite is unaffected.
public sealed class LayerDependencyTests
{
    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Text.Json", "System.Xml",
        "System.Diagnostics", "System.Threading.Channels", "Microsoft",
    ];

    private static readonly System.Reflection.Assembly DomainAssembly = typeof(Domain.Money).Assembly;
    private static readonly System.Reflection.Assembly ApplicationAssembly = typeof(Application.IPaymentGateway).Assembly;

    [Fact]
    public void Domain_depends_on_no_other_layer()
        => AssertNone(Types.InAssembly(DomainAssembly).ShouldNot().HaveDependencyOnAny(Application, Infrastructure));

    [Fact]
    public void Application_does_not_depend_on_Infrastructure()
        => AssertNone(Types.InAssembly(ApplicationAssembly).ShouldNot().HaveDependencyOn(Infrastructure));

    [Fact]
    public void Domain_does_not_use_technical_details()
        => AssertNone(Types.InAssembly(DomainAssembly).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Application_does_not_use_technical_details()
        => AssertNone(Types.InAssembly(ApplicationAssembly).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    private static void AssertNone(ConditionList rule)
    {
        var result = rule.GetResult();
        Assert.True(result.IsSuccessful, "Layer violations: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
EOF
